"""Per-frame mini-MAE anomaly scores generated by the offline exporter."""
from __future__ import annotations

import json
import math
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
DEFAULT_REPORT = ROOT / "outputs" / "mae_frame_report.json"


class MaeScoreProvider:
    def __init__(self, report_path: str | Path | None = None):
        self._path = Path(report_path) if report_path is not None else DEFAULT_REPORT
        self._report: dict | None = None

    def _load(self) -> dict | None:
        if self._report is None and self._path.exists():
            report = json.loads(self._path.read_text())
            if report.get("schema_version") != 1 or not isinstance(
                report.get("clips"), dict
            ):
                raise ValueError(f"Invalid MAE score report schema: {self._path}")
            self._report = report
        return self._report

    @property
    def available(self) -> bool:
        return self._load() is not None

    def frame_value(self, clip_id: str, frame_idx: int) -> float | None:
        """Raw Euclidean distance; None when this clip/frame is not in the report."""
        report = self._load()
        if report is None:
            return None
        clip = report["clips"].get(clip_id)
        if not clip:
            return None
        frame = clip.get("frames", {}).get(str(frame_idx))
        if not frame:
            return None
        value = float(frame["mae_euclidean_raw"])
        if not math.isfinite(value):
            raise ValueError(
                f"Non-finite MAE score in {self._path}: {clip_id}:{frame_idx}"
            )
        return value
